CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260730145651_InitialPostgreSQL') THEN
    CREATE TABLE "FunctionalRequirements" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(10) NOT NULL,
        "Description" text NOT NULL,
        "Module" text NOT NULL,
        "Status" integer NOT NULL,
        "Observation" text NOT NULL,
        CONSTRAINT "PK_FunctionalRequirements" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260730145651_InitialPostgreSQL') THEN
    CREATE TABLE "Materials" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(40) NOT NULL,
        "Name" character varying(120) NOT NULL,
        "Unit" integer NOT NULL,
        "Stock" numeric(18,2) NOT NULL,
        "MinStock" numeric(18,2) NOT NULL,
        "Status" integer NOT NULL,
        "LastEntryDate" date NOT NULL,
        CONSTRAINT "PK_Materials" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

