        "Unit" integer NOT NULL,
        CONSTRAINT "PK_BomItems" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_BomItems_Materials_MaterialId" FOREIGN KEY ("MaterialId") REFERENCES "Materials" ("Id") ON DELETE CASCADE
